mapper.insert:
insert into board_table(
    boardTitle,
    boardContents,
    boardWriter,
    boardPass
) values (
    #{boardTitle},
    #{boardContents},
    #{boardWriter},
    #{boardPass}
);

mapper.update:
update board_table
set boardHits = boardHits + 1
where id = #{id};

mapper.select:
select id, boardTitle, boardContents, boardWriter, boardHits, boardPass,
date_format(createdAt, "%Y-%m-%d %H:%i:%s") as createdAt
from board_table where id = #{id};
